function photoNameFromR2Key(key){
  const base=text(key).split("/").pop()||"";
  return base.replace(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}_/i,"")||"복구 사진";
}

function photoRecordIdFromR2Key(key){
  const parts=text(key).split("/");
  return parts[0]==="solid-fuel-trouble"&&parts.length>=5?text(parts[3]):"";
}

async function recoveredPhotoId(key){
  return `r2-recovered-${(await tokenHash(text(key))).slice(0,40)}`;
}

function uploadedAt(value){
  const date=value?new Date(value):new Date();
  return Number.isNaN(date.getTime())?new Date().toISOString():date.toISOString();
}

function photoRepairResult(row,status="already-complete"){
  return {
    status,
    scannedCount:Number(row?.scanned_count||0),
    recoveredCount:Number(row?.recovered_count||0),
    orphanCount:Number(row?.orphan_count||0),
    missingObjectCount:Number(row?.missing_object_count||0),
    conflictCount:Number(row?.conflict_count||0),
    completedAt:text(row?.completed_at)
  };
}

async function runPhotoIndexRepair(context){
  const db=context.env.DB,bucket=context.env.ATTACHMENTS;
  if(!bucket){
    return {status:"binding-missing",scannedCount:0,recoveredCount:0};
  }

  const completed=await db.prepare(`
    SELECT
      scanned_count,recovered_count,orphan_count,
      missing_object_count,conflict_count,completed_at
    FROM solid_fuel_photo_repair_state
    WHERE repair_key=?
    LIMIT 1
  `).bind(PHOTO_INDEX_REPAIR_KEY).first();

  if(completed) return photoRepairResult(completed);

  const troubleRows=await db.prepare(`
    SELECT id
    FROM solid_fuel_trouble_records
    WHERE deleted_at IS NULL
  `).all();
  const troubleIds=new Set((troubleRows.results||[]).map(row=>text(row.id)).filter(Boolean));
  const existingRows=await allPhotos(db,true);
  const indexedKeys=new Set(existingRows.map(row=>text(row.r2_key)).filter(Boolean));
  const occupiedIds=new Map(existingRows.map(row=>[text(row.id),text(row.r2_key)]).filter(([id,key])=>id&&key));
  const listedKeys=new Set();
  const candidates=[];
  let cursor,scannedCount=0,orphanCount=0,conflictCount=0;

  do{
    const options={
      prefix:PHOTO_R2_PREFIX,
      limit:1000,
      include:["httpMetadata","customMetadata"]
    };
    if(cursor) options.cursor=cursor;

    const page=await bucket.list(options);
    const objects=Array.isArray(page?.objects)?page.objects:[];
    scannedCount+=objects.length;

    for(const object of objects){
      const metadata=object?.customMetadata||{};
      const key=text(object?.key);
      if(!key) continue;
      listedKeys.add(key);
      if(indexedKeys.has(key)) continue;

      const recordId=text(metadata.recordId)||photoRecordIdFromR2Key(key);
      if(!recordId||!troubleIds.has(recordId)){
        orphanCount+=1;
        continue;
      }

      let photoId=text(metadata.photoId);
      if(!photoId||occupiedIds.has(photoId)){
        if(photoId&&occupiedIds.get(photoId)!==key) conflictCount+=1;
        photoId=await recoveredPhotoId(key);
      }
      if(occupiedIds.has(photoId)&&occupiedIds.get(photoId)!==key){
        conflictCount+=1;
        continue;
      }
      occupiedIds.set(photoId,key);

      const originalName=limitedPhotoName(metadata.originalName||photoNameFromR2Key(key));
      candidates.push({
        id:photoId,
        troubleId:recordId,
        key,
        originalName,
        contentType:imageType(originalName),
        fileSize:Number.isFinite(Number(object?.size))?Math.max(0,Number(object.size)):0,
        uploadedById:limited(metadata.uploadedBy,80),
        uploadedByName:limited(metadata.uploadedByName||"R2 자동 복구",120),
        createdAt:uploadedAt(object?.uploaded)
      });
    }

    cursor=page?.truncated&&page?.cursor?text(page.cursor):"";
  }while(cursor);

  const missingObjectCount=existingRows.filter(row=>{
    const key=text(row.r2_key);
    return text(row.upload_state||"ready")==="ready"&&key&&!listedKeys.has(key);
  }).length;

  if(scannedCount===0){
    return {
      status:"empty",
      scannedCount:0,
      recoveredCount:0,
      orphanCount:0,
      missingObjectCount,
      conflictCount:0
    };
  }

  const statements=candidates.map(photo=>db.prepare(`
    INSERT OR IGNORE INTO solid_fuel_trouble_photos(
      id,trouble_id,r2_key,original_name,content_type,file_size,
      uploaded_by_id,uploaded_by_name,created_at,upload_state
    ) VALUES(?,?,?,?,?,?,?,?,?,'ready')
  `).bind(
    photo.id,
    photo.troubleId,
    photo.key,
    photo.originalName,
    photo.contentType,
    photo.fileSize,
    photo.uploadedById,
    photo.uploadedByName,
    photo.createdAt
  ));

  let recoveredCount=0;
  for(let index=0;index<statements.length;index+=50){
    const results=await db.batch(statements.slice(index,index+50));
    recoveredCount+=(Array.isArray(results)?results:[])
      .reduce((sum,result)=>sum+Math.max(0,Number(result?.meta?.changes||0)),0);
  }

  const completedAt=new Date().toISOString();

  const marker=await db.prepare(`
    INSERT INTO solid_fuel_photo_repair_state(
      repair_key,completed_at,scanned_count,recovered_count,
      orphan_count,missing_object_count,conflict_count
    ) VALUES(?,?,?,?,?,?,?)
    ON CONFLICT(repair_key) DO NOTHING
  `).bind(
    PHOTO_INDEX_REPAIR_KEY,
    completedAt,
    scannedCount,
    recoveredCount,
    orphanCount,
    missingObjectCount,
    conflictCount
  ).run();

  if(Number(marker?.meta?.changes||0)!==1){
    const winner=await db.prepare(`
      SELECT
        scanned_count,recovered_count,orphan_count,
        missing_object_count,conflict_count,completed_at
      FROM solid_fuel_photo_repair_state
      WHERE repair_key=?
      LIMIT 1
    `).bind(PHOTO_INDEX_REPAIR_KEY).first();
    if(winner) return photoRepairResult(winner);
    throw new Error("사진 복구 완료 상태를 저장하지 못했습니다.");
  }

  return {
    status:"completed",
    scannedCount,
    recoveredCount,
    orphanCount,
    missingObjectCount,
    conflictCount,
    completedAt
  };
}

async function repairPhotoIndex(context){
  if(photoIndexRepairPromise) return photoIndexRepairPromise;
  photoIndexRepairPromise=runPhotoIndexRepair(context)
    .then(result=>{
      /* 빈 prefix는 완료로 고정하지 않고 같은 isolate의 다음 요청에서도 다시 확인한다. */
      if(!["completed","already-complete"].includes(text(result?.status))) photoIndexRepairPromise=null;
      return result;
    })
    .catch(error=>{
      photoIndexRepairPromise=null;
      throw error;
    });
  return photoIndexRepairPromise;
}

async function reconcilePendingPhotoUploads(context){
  const db=context.env.DB,bucket=context.env.ATTACHMENTS;
  if(!bucket) return {status:"binding-missing",checkedCount:0,finalizedCount:0,removedCount:0,waitingCount:0};

  const result=await db.prepare(`
    SELECT id,trouble_id,r2_key,created_at
    FROM solid_fuel_trouble_photos
    WHERE upload_state='pending'
    ORDER BY created_at,id
    LIMIT ?
  `).bind(PHOTO_PENDING_RECONCILE_LIMIT).all();
  const rows=Array.isArray(result?.results)?result.results:[];
  let finalizedCount=0,removedCount=0,waitingCount=0;
  const now=Date.now();

  for(const row of rows){
    const id=text(row.id),troubleId=text(row.trouble_id),key=text(row.r2_key);
    if(!id||!troubleId||!key) continue;

    const object=await bucket.head(key);
    if(object){
      const updated=await db.prepare(`
        UPDATE solid_fuel_trouble_photos
        SET upload_state='ready'
        WHERE id=? AND trouble_id=? AND r2_key=? AND upload_state='pending'
      `).bind(id,troubleId,key).run();
      finalizedCount+=Math.max(0,Number(updated?.meta?.changes||0));
      continue;
    }

    const createdAt=new Date(text(row.created_at)).getTime();
    const age=Number.isFinite(createdAt)?now-createdAt:Number.POSITIVE_INFINITY;
    if(age<PHOTO_PENDING_GRACE_MS){
      waitingCount+=1;
      continue;
    }

    const removed=await db.prepare(`
      DELETE FROM solid_fuel_trouble_photos
      WHERE id=? AND trouble_id=? AND r2_key=? AND upload_state='pending'
    `).bind(id,troubleId,key).run();
    removedCount+=Math.max(0,Number(removed?.meta?.changes||0));
  }

  return {
    status:rows.length?"checked":"clean",
    checkedCount:rows.length,
    finalizedCount,
    removedCount,
    waitingCount
  };
}

async function reservePhotoUpload(db,photo){
  return db.prepare(`
    INSERT OR IGNORE INTO solid_fuel_trouble_photos(
      id,trouble_id,r2_key,original_name,content_type,file_size,
      uploaded_by_id,uploaded_by_name,created_at,upload_state
    )
    SELECT ?,?,?,?,?,?,?,?,?,'pending'
    WHERE EXISTS(
      SELECT 1
      FROM solid_fuel_trouble_records
      WHERE id=? AND deleted_at IS NULL
    )
      AND (
        SELECT COUNT(*)
        FROM solid_fuel_trouble_photos
        WHERE trouble_id=?
      ) < ?
  `).bind(
    photo.id,
    photo.troubleId,
    photo.key,
    photo.originalName,
    photo.contentType,
    photo.fileSize,
    photo.uploadedById,
    photo.uploadedByName,
    photo.createdAt,
    photo.troubleId,
    photo.troubleId,
    MAX_PHOTO_COUNT
  ).run();
}

function photoKey(id,name,now=new Date()){ return ["solid-fuel-trouble",String(now.getUTCFullYear()),String(now.getUTCMonth()+1).padStart(2,"0"),id,`${crypto.randomUUID()}_${safeName(name)}`].join("/"); }

async function servePhoto(context,id){
  await initialize(context.env.DB);
  const p=await context.env.DB.prepare(`SELECT * FROM solid_fuel_trouble_photos WHERE id=? AND upload_state='ready' LIMIT 1`).bind(id).first();
  if(!p) return json({ok:false,message:"샘플 사진을 찾을 수 없습니다."},404);
  if(!context.env.ATTACHMENTS) return json({ok:false,message:"R2 바인딩 ATTACHMENTS가 등록되지 않았습니다."},500);
  const o=await context.env.ATTACHMENTS.get(p.r2_key); if(!o) return json({ok:false,message:"R2에서 샘플 사진을 찾을 수 없습니다."},404);
  return new Response(o.body,{status:200,headers:{"Content-Type":imageType(p.original_name),"Content-Disposition":photoDisposition(p.original_name),"Cache-Control":"private, no-store","X-Content-Type-Options":"nosniff"}});
}

export async function onRequestGet(context){
  try{
    const url=new URL(context.request.url),photoId=text(url.searchParams.get("photoId"));
    if(photoId) return servePhoto(context,photoId);
    const a=await auth(context); if(a.error) return a.error;
    await initialize(context.env.DB);
    let photoRepair=null,photoConsistency=null;
    try{
      photoConsistency=await reconcilePendingPhotoUploads(context);
    }catch(error){
      console.error("solid fuel pending photo reconciliation",error);
      photoConsistency={status:"failed",checkedCount:0,finalizedCount:0,removedCount:0,waitingCount:0};
    }
    try{
      photoRepair=await repairPhotoIndex(context);
      if(Number(photoRepair?.recoveredCount||0)>0){
        console.info("solid fuel photo index recovered",photoRepair);
      }
    }catch(error){
      console.error("solid fuel photo index repair",error);
      photoRepair={status:"failed",scannedCount:0,recoveredCount:0};
    }
    const [items,unloadingLogs,companyList,companyDir,filterCompanyList]=await Promise.all([
      listTroubles(context.env.DB,url),
      listUnloadings(context.env.DB,url),
      activeCompanies(context.env.DB),
      companyDirectory(context.env.DB),
      filterCompanies(context.env.DB)
    ]);
    return json({
      ok:true,
      items,
      unloadingLogs,
      companies:companyList,
      companyDirectory:companyDir,
      filterCompanies:filterCompanyList,
      photoRepair:{...photoRepair,consistency:photoConsistency},
      permissions:{canCreate:true,canEdit:true,canDelete:a.user.isAdmin,canUploadPhoto:true,canManageUnloading:true,canManageCompanies:true},
      user:a.user,
      seed:{trouble:21,unloading:309}
    });
  }catch(e){console.error("solid fuel V3 GET",e);return json({ok:false,message:e?.message||"조회 중 오류가 발생했습니다."},Number(e?.status)||500);}
}

export async function onRequestPost(context){
  const photoReservations=[];
  try{
    const a=await auth(context); if(a.error) return a.error; await initialize(context.env.DB); const user=a.user;
    const ct=text(context.request.headers.get("Content-Type")).toLowerCase();
    if(ct.includes("multipart/form-data")){
      if(!context.env.ATTACHMENTS) return json({ok:false,message:"R2 바인딩 ATTACHMENTS가 등록되지 않았습니다."},500);
      const f=await context.request.formData(),recordId=text(f.get("recordId")),rec=await findTrouble(context.env.DB,recordId);
      if(!rec) return json({ok:false,message:"사진을 추가할 Trouble 기록을 찾을 수 없습니다."},404);
      const fileEntries=f.getAll("files"),files=fileEntries.filter(x=>x instanceof File);
      if(!files.length) return json({ok:false,message:"업로드할 사진을 선택해 주세요."},400);
      if(files.length!==fileEntries.length) return json({ok:false,message:"사진 첨부 형식을 확인해 주세요."},400);

      /* 한 파일이라도 잘못되면 R2/D1을 전혀 쓰기 전에 요청 전체를 거절한다. */
      for(const file of files){
        if(Number(file.size||0)<=0) return json({ok:false,message:`${file.name||"선택한 사진"} 파일이 비어 있습니다.`},400);
        if(!PHOTO_EXTENSIONS.has(ext(file.name))) return json({ok:false,message:`${file.name} 파일은 등록할 수 없습니다.`},400);
        if(Number(file.size||0)>MAX_PHOTO_SIZE) return json({ok:false,message:`${file.name} 파일은 10MB를 초과합니다.`},400);
      }

      try{
        await reconcilePendingPhotoUploads(context);
        await repairPhotoIndex(context);
      }catch(error){
        console.error("solid fuel photo consistency before upload",error);
      }

      const countRow=await context.env.DB.prepare(`SELECT COUNT(*) count_value FROM solid_fuel_trouble_photos WHERE trouble_id=?`).bind(recordId).first();
      if(Number(countRow?.count_value||0)+files.length>MAX_PHOTO_COUNT) return json({ok:false,message:`신규 사진은 기록당 최대 ${MAX_PHOTO_COUNT}개까지 등록할 수 있습니다.`},400);
      const now=new Date().toISOString();

      for(const file of files){
        const id=crypto.randomUUID(),
          originalName=limitedPhotoName(file.name),
          key=photoKey(recordId,originalName,new Date(now)),
          contentType=imageType(originalName),
          photo={
            id,
            troubleId:recordId,
            key,
            originalName,
            contentType,
            fileSize:Number(file.size||0),
            uploadedById:limited(user.employeeNo,80),
            uploadedByName:limited(user.name,120),
            createdAt:now
          };

        /*
          D1에 pending 슬롯을 먼저 원자적으로 예약한다.
          COUNT 조건은 INSERT 한 문장 안에 있어 동시 업로드도 4개 제한을 넘지 못한다.
        */
        const reserved=await reservePhotoUpload(context.env.DB,photo);
        if(Number(reserved?.meta?.changes||0)!==1){
          const currentRecord=await findTrouble(context.env.DB,recordId);
          if(!currentRecord) throw Object.assign(new Error("사진을 추가할 Trouble 기록을 찾을 수 없습니다."),{status:404});
          const currentCount=await context.env.DB.prepare(`SELECT COUNT(*) count_value FROM solid_fuel_trouble_photos WHERE trouble_id=?`).bind(recordId).first();
          if(Number(currentCount?.count_value||0)>=MAX_PHOTO_COUNT){
            throw Object.assign(new Error(`신규 사진은 기록당 최대 ${MAX_PHOTO_COUNT}개까지 등록할 수 있습니다.`),{status:400});
          }
          throw Object.assign(new Error("사진 저장 예약 정보가 충돌했습니다. 다시 시도해 주세요."),{status:409});
        }
        photoReservations.push(photo);

        await context.env.ATTACHMENTS.put(key,file.stream(),{
          httpMetadata:{contentType},
          customMetadata:{
            recordId,
            photoId:id,
            uploadedBy:photo.uploadedById,
            uploadedByName:photo.uploadedByName,
            originalName,
            contentType
          }
        });

        const finalized=await context.env.DB.prepare(`
          UPDATE solid_fuel_trouble_photos
          SET upload_state='ready'
          WHERE id=? AND trouble_id=? AND r2_key=? AND upload_state='pending'
        `).bind(id,recordId,key).run();
        if(Number(finalized?.meta?.changes||0)!==1){
          const linked=await context.env.DB.prepare(`
            SELECT id
            FROM solid_fuel_trouble_photos
            WHERE id=? AND trouble_id=? AND r2_key=? AND upload_state='ready'
            LIMIT 1
          `).bind(id,recordId,key).first();
          if(!linked) throw new Error("사진 저장 완료 상태를 반영하지 못했습니다. 다시 시도해 주세요.");
        }
      }
      return json({ok:true,recordId,uploadedCount:files.length},201);
    }
    const b=await context.request.json(),entity=text(b.entity||"trouble").toLowerCase();

    if(entity==="company"){
      const companyName=cleanCompany(b.companyName);
      if(!companyName) return json({ok:false,message:"추가할 업체명을 입력해 주세요."},400);
      await ensureCompanyActive(context.env.DB,companyName);
      return json({ok:true,entity:"company",companyName,isActive:true},201);
    }

    /*
      V3.1 선택 입력
      - 모든 공통 입력값은 선택사항
      - 일자/시간이 비어 있어도 저장 가능
      - 입고/출고가 모두 있을 때만 소요시간 계산
      - Trouble 상세도 선택사항
    */
    if(entity==="combined"){
      const date=optionalDate(b.unloadingDate||b.occurrenceDate),
        arrival=optionalClock(b.arrivalTime),
        departure=optionalClock(b.departureTime),
        company=cleanCompany(b.companyName),
        vehicle=limited(b.vehicleNo,40),
        silo=limited(b.siloRoute,80),
        equipment=limited(b.equipment,500),
        note=limited(b.note,3000);

      if(date===null) return json({ok:false,message:"일자 형식을 확인해 주세요."},400);
      if(arrival===null||departure===null) return json({ok:false,message:"입고/출고 시간 형식을 확인해 주세요."},400);

      const duration=durationMinutes(arrival,departure),
        durationKnown=Number.isFinite(duration)?1:0,
        durationStored=durationKnown?duration:0,
        unloadingId=crypto.randomUUID(),
        troubleId=crypto.randomUUID(),
        now=new Date().toISOString(),
        troublePrefix=equipment?`[Trouble] ${equipment}`:"[Trouble]",
        unloadingNote=limited(`${troublePrefix}${note?`\n${note}`:""}`,3000);

      if(company) await ensureCompanyPresent(context.env.DB,company);

      const unloadingStatement=context.env.DB.prepare(`INSERT INTO solid_fuel_unloading_logs(
        id,source_key,unloading_date,arrival_time,departure_time,duration_minutes,duration_known,company_name,vehicle_no,silo_route,
        silo_a_company,silo_a_vehicle,silo_b_company,silo_b_vehicle,day_company,day_vehicle,note,version,
        created_by_id,created_by_name,updated_by_id,updated_by_name,created_at,updated_at
      ) VALUES(?,NULL,?,?,?,?,?,?,?,?,'','','','','','',?,1,?,?,?,?,?,?)`)
      .bind(unloadingId,date,arrival,departure,durationStored,durationKnown,company,vehicle,silo,unloadingNote,user.employeeNo,user.name,user.employeeNo,user.name,now,now);

      const troubleStatement=context.env.DB.prepare(`INSERT INTO solid_fuel_trouble_records(
        id,source_key,occurrence_date,company_name,vehicle_no,equipment,note,legacy_photo_path,version,
        created_by_id,created_by_name,updated_by_id,updated_by_name,created_at,updated_at
      ) VALUES(?,NULL,?,?,?,?,?,'',1,?,?,?,?,?,?)`)
      .bind(troubleId,date,company,vehicle,equipment,note,user.employeeNo,user.name,user.employeeNo,user.name,now,now);

      await context.env.DB.batch([
        unloadingStatement,
        troubleStatement
      ]);

      return json({
        ok:true,
        entity:"combined",
        unloadingId,
        troubleId,
        recordId:troubleId,
        durationKnown:Boolean(durationKnown),
        durationMinutes:durationKnown?duration:null,
        version:1
      },201);
    }

    if(entity==="unloading"){
      const date=optionalDate(b.unloadingDate),
        arrival=optionalClock(b.arrivalTime),
        departure=optionalClock(b.departureTime),
        company=cleanCompany(b.companyName);

      if(date===null) return json({ok:false,message:"하역 일자 형식을 확인해 주세요."},400);
      if(arrival===null||departure===null) return json({ok:false,message:"입고/출고 시간 형식을 확인해 주세요."},400);

      const duration=durationMinutes(arrival,departure),
        durationKnown=Number.isFinite(duration)?1:0,
        durationStored=durationKnown?duration:0,
        id=crypto.randomUUID(),
        now=new Date().toISOString();

      if(company) await ensureCompanyPresent(context.env.DB,company);

      await context.env.DB.prepare(`INSERT INTO solid_fuel_unloading_logs(
        id,source_key,unloading_date,arrival_time,departure_time,duration_minutes,duration_known,company_name,vehicle_no,silo_route,
        silo_a_company,silo_a_vehicle,silo_b_company,silo_b_vehicle,day_company,day_vehicle,note,version,
        created_by_id,created_by_name,updated_by_id,updated_by_name,created_at,updated_at
      ) VALUES(?,NULL,?,?,?,?,?,?,?,?,'','','','','','',?,1,?,?,?,?,?,?)`)
      .bind(id,date,arrival,departure,durationStored,durationKnown,company,limited(b.vehicleNo,40),limited(b.siloRoute,80),limited(b.note,3000),user.employeeNo,user.name,user.employeeNo,user.name,now,now).run();

      return json({ok:true,id,recordId:id,version:1,durationKnown:Boolean(durationKnown),durationMinutes:durationKnown?duration:null},201);
    }

    const date=optionalDate(b.occurrenceDate),
      equipment=limited(b.equipment,500),
      company=cleanCompany(b.companyName);

    if(date===null) return json({ok:false,message:"발생 날짜 형식을 확인해 주세요."},400);
    if(company) await ensureCompanyPresent(context.env.DB,company);

    const id=crypto.randomUUID(),now=new Date().toISOString();
    await context.env.DB.prepare(`INSERT INTO solid_fuel_trouble_records(
      id,source_key,occurrence_date,company_name,vehicle_no,equipment,note,legacy_photo_path,version,
      created_by_id,created_by_name,updated_by_id,updated_by_name,created_at,updated_at
    ) VALUES(?,NULL,?,?,?,?,?,'',1,?,?,?,?,?,?)`).bind(id,date,company,limited(b.vehicleNo,40),equipment,limited(b.note,3000),user.employeeNo,user.name,user.employeeNo,user.name,now,now).run();

    return json({ok:true,id,recordId:id,version:1},201);
  }catch(e){
    for(const photo of [...photoReservations].reverse()){
      try{
        await context.env.DB?.prepare(`
          UPDATE solid_fuel_trouble_photos
          SET upload_state='pending'
          WHERE id=? AND trouble_id=? AND r2_key=?
        `).bind(photo.id,photo.troubleId,photo.key).run();
      }catch(error){
        console.error("solid fuel photo rollback pending",error);
      }

      let objectRemoved=false;
      try{
        await context.env.ATTACHMENTS?.delete(photo.key);
        objectRemoved=true;
      }catch(error){
        /* R2 삭제 실패 시 pending D1 행을 남겨 다음 요청의 consistency 검사에 맡긴다. */
        console.error("solid fuel photo rollback R2",error);
      }

      if(objectRemoved){
        try{
          await context.env.DB?.prepare(`
            DELETE FROM solid_fuel_trouble_photos
            WHERE id=? AND trouble_id=? AND r2_key=?
          `).bind(photo.id,photo.troubleId,photo.key).run();
        }catch(error){
          console.error("solid fuel photo rollback D1",error);
        }
      }
    }
    console.error("solid fuel V3 POST",e);return json({ok:false,message:e?.message||"저장 중 오류가 발생했습니다."},Number(e?.status)||500);
  }
}

export async function onRequestPut(context){
  try{
    const a=await auth(context);
    if(a.error) return a.error;
    await initialize(context.env.DB);

    const b=await context.request.json(),
      entity=text(b.entity||"trouble").toLowerCase(),
      u=a.user,
      now=new Date().toISOString();

    if(entity==="company"){
      const companyName=cleanCompany(b.companyName),
        isActive=b.isActive===true||b.isActive===1||b.isActive==="1";

      if(!companyName) return json({ok:false,message:"업체명을 확인해 주세요."},400);

      const result=await context.env.DB.prepare(`
        UPDATE solid_fuel_companies
        SET is_active=?,updated_at=CURRENT_TIMESTAMP
        WHERE company_name=?
      `).bind(isActive?1:0,companyName).run();

      if(Number(result?.meta?.changes||0)!==1){
        if(isActive){
          await ensureCompanyActive(context.env.DB,companyName);
        }else{
          return json({ok:false,message:"업체 목록에서 대상을 찾을 수 없습니다."},404);
        }
      }

      return json({ok:true,entity:"company",companyName,isActive});
    }

    const id=text(b.id||b.recordId),
      version=Number(b.version);

    if(!id||!Number.isInteger(version)||version<1){
      return json({ok:false,message:"수정 대상/버전 정보가 올바르지 않습니다."},400);
    }

    if(entity==="unloading"){
      const date=optionalDate(b.unloadingDate),
        arrival=optionalClock(b.arrivalTime),
        departure=optionalClock(b.departureTime),
        company=cleanCompany(b.companyName);

      if(date===null) return json({ok:false,message:"하역 일자 형식을 확인해 주세요."},400);
      if(arrival===null||departure===null) return json({ok:false,message:"입고/출고 시간 형식을 확인해 주세요."},400);

      const duration=durationMinutes(arrival,departure),
        durationKnown=Number.isFinite(duration)?1:0,
        durationStored=durationKnown?duration:0;

      if(company) await ensureCompanyPresent(context.env.DB,company);

      const r=await context.env.DB.prepare(`
        UPDATE solid_fuel_unloading_logs
        SET unloading_date=?,arrival_time=?,departure_time=?,duration_minutes=?,duration_known=?,company_name=?,vehicle_no=?,silo_route=?,note=?,
            version=version+1,updated_by_id=?,updated_by_name=?,updated_at=?
        WHERE id=? AND version=? AND deleted_at IS NULL
      `)
      .bind(
        date,
        arrival,
        departure,
        durationStored,
        durationKnown,
        company,
        limited(b.vehicleNo,40),
        limited(b.siloRoute,80),
        limited(b.note,3000),
        u.employeeNo,
        u.name,
        now,
        id,
        version
      )
      .run();

      if(Number(r?.meta?.changes||0)!==1){
        return json({ok:false,code:"VERSION_CONFLICT",message:"다른 사용자가 먼저 수정했습니다. 새로고침 후 다시 시도해 주세요."},409);
      }

      return json({ok:true,id,version:version+1,durationKnown:Boolean(durationKnown),durationMinutes:durationKnown?duration:null});
    }

    const date=optionalDate(b.occurrenceDate),
      equipment=limited(b.equipment,500),
      company=cleanCompany(b.companyName);

    if(date===null) return json({ok:false,message:"날짜 형식을 확인해 주세요."},400);
    if(company) await ensureCompanyPresent(context.env.DB,company);

    const r=await context.env.DB.prepare(`
      UPDATE solid_fuel_trouble_records
      SET occurrence_date=?,company_name=?,vehicle_no=?,equipment=?,note=?,
          version=version+1,updated_by_id=?,updated_by_name=?,updated_at=?
      WHERE id=? AND version=? AND deleted_at IS NULL
    `)
    .bind(
      date,
      company,
      limited(b.vehicleNo,40),
      equipment,
      limited(b.note,3000),
      u.employeeNo,
      u.name,
      now,
      id,
      version
    )
    .run();

    if(Number(r?.meta?.changes||0)!==1){
      return json({ok:false,code:"VERSION_CONFLICT",message:"다른 사용자가 먼저 수정했습니다. 새로고침 후 다시 시도해 주세요."},409);
    }

    return json({ok:true,id,version:version+1});
  }catch(e){
    console.error("solid fuel V3.1 PUT",e);
    return json({ok:false,message:e?.message||"수정 중 오류가 발생했습니다."},500);
  }
}

export async function onRequestDelete(context){
  try{
    const a=await auth(context); if(a.error) return a.error; await initialize(context.env.DB); const url=new URL(context.request.url),photoId=text(url.searchParams.get("photoId"));
    if(photoId){
      const p=await context.env.DB.prepare(`SELECT * FROM solid_fuel_trouble_photos WHERE id=? LIMIT 1`).bind(photoId).first();
      if(!p) return json({ok:false,message:"삭제할 샘플 사진을 찾을 수 없습니다."},404);
      if(context.env.ATTACHMENTS&&text(p.r2_key)) await context.env.ATTACHMENTS.delete(p.r2_key);
      await context.env.DB.prepare(`DELETE FROM solid_fuel_trouble_photos WHERE id=?`).bind(photoId).run();
      return json({ok:true,deletedPhotoId:photoId});
    }
    if(!a.user.isAdmin) return json({ok:false,message:"기록 삭제는 파트장 또는 관리자 권한이 필요합니다."},403);
    const id=text(url.searchParams.get("id")),entity=text(url.searchParams.get("entity")||"trouble").toLowerCase();
    if(!id) return json({ok:false,message:"삭제할 기록 ID가 필요합니다."},400);
    const now=new Date().toISOString(),table=entity==="unloading"?"solid_fuel_unloading_logs":"solid_fuel_trouble_records";
    const r=await context.env.DB.prepare(`UPDATE ${table} SET deleted_at=?,deleted_by_id=?,deleted_by_name=?,updated_at=? WHERE id=? AND deleted_at IS NULL`).bind(now,a.user.employeeNo,a.user.name,now,id).run();
    if(Number(r?.meta?.changes||0)!==1) return json({ok:false,message:"삭제할 기록을 찾을 수 없습니다."},404);
    return json({ok:true,deletedId:id,entity});
  }catch(e){console.error("solid fuel V3 DELETE",e);return json({ok:false,message:e?.message||"삭제 중 오류가 발생했습니다."},500);}
}
